// Protected vector retrieval only. Embeddings are generated by the existing local 384D model.
// Never embed or expose API tokens in this source code.
export default {
  async fetch(request, env) {
    if (request.method !== "POST") return new Response("Not found", { status: 404 });
    const expected = env.TIMDR_SEARCH_TOKEN;
    const supplied = request.headers.get("Authorization");
    if (!expected || !supplied || supplied !== `Bearer ${expected}`) {
      return new Response("Unauthorized", { status: 401 });
    }
    const url = new URL(request.url);
    if (url.pathname !== "/search") return new Response("Not found", { status: 404 });
    let body;
    try { body = await request.json(); } catch { return new Response("Invalid JSON", { status: 400 }); }
    const vector = body.vector;
    if (!Array.isArray(vector) || vector.length !== 384 ||
        !vector.every(x => typeof x === "number" && Number.isFinite(x))) {
      return new Response("Expected 384 finite numbers", { status: 400 });
    }
    const topK = Number.isInteger(body.topK) ? Math.max(1, Math.min(10, body.topK)) : 5;
    const allowed = ["branch", "source_type", "repo", "status"];
    const filter = {};
    if (body.filter && typeof body.filter === "object" && !Array.isArray(body.filter)) {
      for (const key of allowed) {
        if (Object.hasOwn(body.filter, key)) {
          if (typeof body.filter[key] !== "string" || body.filter[key].length > 128)
            return new Response("Invalid filter", { status: 400 });
          filter[key] = body.filter[key];
        }
      }
    }
    try {
      const options = { topK, returnMetadata: "all" };
      if (Object.keys(filter).length) options.filter = filter;
      const result = await env.VECTORIZE.query(vector, options);
      return Response.json({
        count: result.count,
        matches: result.matches.map(m => ({
          id: m.id, score: m.score, metadata: m.metadata
        }))
      }, { headers: { "Cache-Control": "no-store" } });
    } catch {
      return new Response("Vector search unavailable", { status: 503 });
    }
  }
};
